from pathlib import Path

def edit(name,old,new):
    p=Path(name);s=p.read_text(encoding='utf-8')
    if old not in s:raise RuntimeError('Missing anchor: '+name+' '+old[:60])
    p.write_text(s.replace(old,new),encoding='utf-8')

